reply:
The brief maps to a two-column layout: a heading and status filter on the left, and a sortable table of the eight items on the right. The catalog has no filter function, so the segmented control records the selected status but does not yet hide rows. The client needs to wire that behavior.

<a2ui-json>
[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "work_items",
      "catalogId": "https://a2uicatalog.ai/catalog/d-t4.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "work_items",
      "components": [
        {
          "id": "root",
          "component": "columns",
          "cols": 2,
          "gap": "1.5rem",
          "align": "top",
          "items": [
            {
              "blocks": [
                {
                  "id": "items_heading",
                  "component": "heading",
                  "text": "Work items"
                },
                {
                  "id": "status_filter",
                  "component": "segmented_control",
                  "name": "status_filter",
                  "selected_value": "all",
                  "options": "[{\"label\":\"All\",\"value\":\"all\"},{\"label\":\"Open\",\"value\":\"open\"},{\"label\":\"In progress\",\"value\":\"in_progress\"},{\"label\":\"Blocked\",\"value\":\"blocked\"},{\"label\":\"Done\",\"value\":\"done\"}]"
                }
              ]
            },
            {
              "blocks": [
                {
                  "id": "items_table",
                  "component": "data_table_sortable",
                  "headers": ["Title", "Status", "Detail"],
                  "rows": [
                    ["Login API migration", "In progress", "Token refresh endpoints moved to new auth service"],
                    ["Invoice export", "Done", "CSV export verified against finance sample"],
                    ["Mobile push alerts", "Blocked", "Waiting on APNs certificate renewal"],
                    ["Search indexing", "Open", "Reindex job scheduled for nightly run"],
                    ["Billing webhook retries", "In progress", "Exponential backoff added, tests pending"],
                    ["Onboarding copy review", "Open", "Draft copy sent to legal for sign-off"],
                    ["Dashboard charts", "Done", "Chart library upgraded and visual QA passed"],
                    ["Audit log retention", "Blocked", "Storage policy decision needed from security"]
                  ]
                }
              ]
            }
          ]
        }
      ]
    }
  }
]
</a2ui-json>
